// FactRevenuePrediction - Power Query M
// Generated by src/powerbi_prep.py (STEP 11). Source: outputs/tables/revenue_predictions.csv (Step 8)
// SYNTHETIC DATA. Change DataFolder once, in the DataFolder parameter, not here.
let
    Source = Csv.Document(
        File.Contents(DataFolder & "FactRevenuePrediction.csv"),
        [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed = Table.TransformColumnTypes(Promoted, {
        {"Customer_ID", type text},
        {"Cutoff_Date", type date},
        {"Target_Period", type text},
        {"Target_Quarter_Start", type date},
        {"Target_Quarter", type text},
        {"Split", type text},
        {"Region", type text},
        {"Main_Category", type text},
        {"RFM_Segment_At_Cutoff", type text},
        {"Cluster_ID", Int64.Type},
        {"Cluster_Label_At_Cutoff", type text},
        {"Actual_Revenue", type number},
        {"Predicted_Revenue", type number},
        {"Naive_Baseline", type number},
        {"Prediction_Error", type number},
        {"Absolute_Error", type number},
        {"Percentage_Error_%", type number}
    }),
    Result = Typed
in
    Result
